const o=r=>{switch(r){case"USD":return"$";case"EUR":return"€";case"COP":default:return"$"}},i=(r,t,n="miles",c)=>{const e=o(t);if(n==="miles"){if(r>=1e6){const s=r/1e6;return`${e}${s.toFixed(2).replace(".",",")}M`}else if(r>=1e3)return`${e}${Math.round(r/1e3)}K`;return`${e}${Math.round(r)}`}return new Intl.NumberFormat("es-CO",{style:"currency",currency:t,minimumFractionDigits:0}).format(r)};export{i as f};
